let lang=new URLSearchParams(location.search).get('lang')==='en'?'en':'ru';
const isCase=location.pathname.endsWith('finelo.html');
const t=(ru,en)=>lang==='ru'?ru:en;
const href=(page,hash='')=>`${page}?lang=${lang}${hash}`;
const external=(url,label)=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;
const screen=(name,ru,en)=>`<button class="screen" data-image="${name}" data-caption="${t(ru,en)}" aria-label="${t('Увеличить: ','Enlarge: ')+t(ru,en)}">${name==='tools'?`<span class="tools-frame"><img src="assets/tools.png" alt="${t(ru,en)}" loading="lazy" width="375" height="872"><span class="tools-tabbar" aria-hidden="true"><img src="assets/tools.png" alt="" loading="lazy" width="375" height="872"></span></span>`:`<img src="assets/${name}.png" alt="${t(ru,en)}" loading="lazy" width="375" height="812">`}<span class="zoom-hint" aria-hidden="true">↗</span></button>`;
const img=(name,alt)=>`<img src="assets/${name}.png" alt="${alt}" width="375" height="812">`;
const flower=`<svg class="flower" viewBox="0 0 100 100" aria-hidden="true"><g class="flower-petals" fill="currentColor"><ellipse cx="50" cy="50" rx="14" ry="48"/><ellipse cx="50" cy="50" rx="14" ry="48" transform="rotate(60 50 50)"/><ellipse cx="50" cy="50" rx="14" ry="48" transform="rotate(120 50 50)"/><circle cx="50" cy="50" r="10" fill="var(--paper)"/></g></svg>`;
