const skillOrder=[0,6,9,1,7,10,2,8,11,3,12,14,4,13,16,5,15,20,18,17,19];
function home(){return `<main id="main" class="wrap"><section class="hero"><div class="eyebrow"><span class="dot"></span>${t('ПРОДУКТОВЫЙ ДИЗАЙНЕР · АЛМАТЫ','PRODUCT DESIGNER · ALMATY')}</div><h1>${t('Привет, я Люда.<br>Проектирую интерфейсы,<br> которые <em>легко понять.</em>','Hi, I’m Lyuda.<br>I design interfaces<br> that <em>make sense.</em>')}</h1>${flower}<div class="hero-bottom"><p>${t('Проектирую мобильные и веб-продукты: от первых вопросов пользователям до запуска и работы с результатами.','I design mobile and web products, from asking the first questions to shipping and learning from the results.')}</p></div></section><section id="work" aria-label="${t('Проекты','Projects')}"><a class="feature" href="${href('finelo.html')}"><div class="feature-copy"><div class="feature-tags"><span>B2C</span><span>EdTech</span><span>2026</span></div><h3>Finelo</h3><p class="feature-description">${t('Трейдинг и инвестиции:<br>от теории к практике','Trading and investing:<br>from theory to practice')}</p><p class="feature-platform">${t('Мобильное приложение и веб','Mobile app and web')}</p><p class="feature-scope">${t('Мой вклад — от исследований<br>до запуска и анализа результатов.','My work: from research<br>to launch and measuring results.')}</p></div><div class="feature-screens" aria-hidden="true">${img('pathway','')}${img('complete','')}${img('practice','')}</div></a><div class="other-projects">${works.slice(0,3).map(workRow).join('')}</div></section><section class="web-works"><div class="section-top"><h2>${t('Ещё немного веба','A little more web')}</h2><span>${t('Интерфейсы для большого экрана','Designing for larger screens')}</span></div>${works.slice(3).map(workRow).join('')}</section><section id="about" class="about"><div class="about-title"><h2>${t('Немного<br>обо мне','A little<br>about me')}</h2><div class="about-art">${aboutIllustration}</div></div><div class="about-copy"><p>${t('Разбираюсь в задаче, задаю вопросы и проверяю гипотезы. Соединяю потребности людей, цели продукта и возможности разработки.','I get to the heart of a problem, ask questions and test hypotheses. I bring together people’s needs, product goals and engineering constraints.')}</p><p>${t('Внимательна к деталям: от текста на кнопке до состояний интерфейса. Беру ответственность за задачу и довожу решение до запуска вместе с командой.','I pay attention to details, from button copy to interface states. I take ownership of a task and work with the team to bring the solution to launch.')}</p><p>${t('В свободное время читаю, вяжу классные штуки, хожу в походы и катаюсь на горных лыжах, фанатею по вселенной Гарри Поттера.','Outside work, I read, knit fun things, hike and ski, and love the Harry Potter universe.')}</p><a class="text-link" href="assets/Lyudmila-Zapevalova-CV.pdf" target="_blank">${t('Подробнее в резюме','Read my CV')} ↗</a></div></section><section class="skills-section" id="skills"><div class="skills-heading"><h2>${t('Что я умею','What I bring')}</h2></div><ul class="skill-cloud">${skillOrder.map(i=>`<li class="skill-chip skill-${skillGroups[i]}" style="--tilt:${i%2===0?'-2':'2'}deg"><span>${t(...skills[i])}</span></li>`).join('')}</ul></section></main>`}
function caption(title,desc){return `<figcaption class="media-caption"><h3>${title}</h3><p>${desc}</p></figcaption>`}
function intro(num,title,desc=''){return `<div class="chapter-intro"><div class="chapter-index">${num}</div><div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div></div>`}
function productCaption(title,desc){return `<figcaption class="product-caption"><h3>${title}</h3><p>${desc}</p></figcaption>`}
function finelo(){return `<main id="main" class="wrap"><a class="back" href="${href('index.html','#work')}">← ${t('Все работы','All work')}</a><section class="case-head finelo-overview"><div class="case-summary"><div class="case-title-row"><h1>Finelo</h1><div class="case-external hover-links">${external('https://finelo.com',t('Сайт продукта','Product website'))}${external('https://apps.apple.com/si/app/finelo-master-trading/id6670422243','App Store')}</div></div><div class="case-tags"><span class="skill-chip skill-tools"><span>B2C</span></span><span class="skill-chip skill-design"><span>EdTech</span></span><span class="skill-chip skill-research"><span>Mobile & Web</span></span></div><p class="case-description">${t('Finelo — подписочное приложение для обучения инвестициям и трейдингу. Короткие уроки, практические задания и игровые механики помогают изучать основы и применять знания в виртуальном симуляторе. Основная аудитория — пользователи из США.','Finelo is a subscription app for learning investing and trading. Short lessons, practical exercises and game mechanics help users learn the basics and apply their knowledge in a virtual simulator. Its main audience is users in the US.')}</p><div class="case-facts"><div><span class="label">${t('Компания','Company')}</span><p>Zimran</p></div><div><span class="label">${t('Моя роль','My role')}</span><p>${t('Продуктовый дизайнер','Product Designer')}</p></div></div></div><aside class="team-card"><h2>${t('Команда продукта','Product team')}</h2><ul>${[['Продакт-менеджер','Product manager','1'],['Продуктовые дизайнеры','Product designers','4'],['Rive-аниматор','Rive animator','1'],['Learning дизайнеры','Learning Designers','4'],['Разработчики','Developers','8'],['Аналитик','Analyst','1']].map(([ru,en,count])=>`<li><span>${t(ru,en)}</span><span>${count}</span></li>`).join('')}</ul></aside></section><nav class="chapter-nav" aria-label="${t('Разделы кейса','Case sections')}"><div class="inner">${[['product','Как устроен Finelo','Inside Finelo'],['contribution','Мой вклад','My contribution'],['problems','Проблематика','The challenges'],['support','Поддержка','Support'],['webapp','Web → App','Web → App'],['upsells','Дополнения к подписке','Subscription add-ons'],['research','Исследования','Research'],['system','Дизайн-система','Design system']].map(([id,ru,en])=>`<a href="#${id}">${t(ru,en)}</a>`).join('')}</div></nav>
<section class="chapter product-overview" id="product"><h2 class="product-title">${t('Как устроен Finelo','Inside Finelo')}</h2><figure class="visual-block">${productCaption(t('Уроки и практика','Lessons and practice'),t('Пользователь последовательно изучает темы, а в конце каждой проходит проверочный квиз. Весь путь обучения виден на главном экране. Короткие объяснения чередуются с заданиями: сопоставить варианты ответов или выбрать покупку либо продажу по тренду на графике. После каждого задания пользователь сразу получает обратную связь.','Users work through topics in order and take a quiz at the end of each one. The home screen shows the entire learning path. Short explanations alternate with exercises: matching answers or choosing to buy or sell based on a chart trend. Users get immediate feedback after each task.'))}<div class="screen-stage mint">${screen('quiz','Задание в уроке','Lesson exercise')}${screen('practice','Покупка или продажа по тренду на графике','Buy or sell based on a chart trend')}${screen('feedback','Обратная связь после задания','Feedback after an exercise')}</div></figure><figure class="visual-block">${productCaption(t('Игровые механики','Game mechanics'),t('Награды за уроки, серии занятий и место в рейтинге помогают видеть прогресс и добавляют игровой интерес.','Lesson rewards, learning streaks and leaderboard progress bring a sense of achievement and play to the learning experience.'))}<div class="screen-stage peach">${screen('complete','Урок завершён','Lesson complete')}${screen('streak','Серия занятий','Learning streak')}${screen('leaderboard','Место в рейтинге','Leaderboard progress')}</div></figure><figure class="visual-block">${productCaption(t('Инструменты для практики','Tools for practice'),t('Виртуальный симулятор, AI-ментор, анализатор графиков и другие инструменты помогают применять знания на практике.','A virtual simulator, AI mentor, chart analyzer and other tools help users put their knowledge into practice.'))}<div class="screen-stage blue">${screen('tools','Инструменты для практики','Practice tools overview')}${screen('simulator','Виртуальный симулятор','Virtual trading simulator')}${screen('mentor','AI-ментор','AI mentor')}</div></figure></section>
<section class="chapter contribution-overview" id="contribution"><h2 class="section-title">${t('Мой вклад','My contribution')}</h2><p class="contribution-description">${t('Работала над переходом в приложение, онбордингом, поддержкой, дополнительными покупками и другими сценариями. Вела задачи от исследования до запуска: готовила макеты, описывала поведение и анимацию, проверяла реализацию. Вместе с разработчиками запускала тесты, собирала дашборды и следила за результатами.','I worked on the transition to the app, onboarding, support, add-ons and other flows. I owned tasks from research to launch: designed screens, documented interactions and motion, and checked the implementation. I ran tests with developers, built dashboards and tracked the results.')}</p><div class="work-gallery"><figure class="task-tile task-wide"><div class="task-stage blue">${screen('work-books','Магазин учебных материалов','Learning materials store')}${screen('work-book-details','Описание и покупка книги','Book details and purchase')}${screen('work-book-library','Книга добавлена в библиотеку','Book added to the library')}</div><figcaption><h3>${t('Магазин учебных материалов','Learning materials store')}</h3></figcaption></figure><figure class="task-tile"><div class="task-stage mint">${screen('work-force-update','Обязательное обновление приложения','Required app update')}${screen('work-soft-update','Предложение обновить приложение','Optional app update')}</div><figcaption><h3>${t('Обновление приложения','App updates')}</h3></figcaption></figure><figure class="task-tile task-wide"><div class="task-stage lavender">${screen('work-store-en','Стор-скрин на английском','English store screenshot')}${screen('work-store-fr','Стор-скрин на французском','French store screenshot')}${screen('work-store-ar','Стор-скрин на арабском','Arabic store screenshot')}</div><figcaption><h3>${t('Локализация и стор-скрины','Localization and store listings')}</h3></figcaption></figure><figure class="task-tile"><div class="task-stage yellow">${screen('work-welcome','Первый вход в приложение','First entry into the app')}</div><figcaption><h3>${t('Первый вход в приложение','First entry into the app')}</h3></figcaption></figure></div></section>
<section class="chapter problem-overview" id="problems"><h2 class="section-title">${t('Проблематика','The challenges')}</h2><p class="problem-intro">${t('После покупки пользователям было непросто перейти из веб-воронки к обучению в приложении.','After purchasing, users struggled to move from the web funnel to learning in the app.')}</p><ul class="problem-list"><li>${t('После покупки часть пользователей так и не переходила из веба в мобильное приложение.','Some users dropped off after purchasing, before reaching the mobile app.')}</li><li>${t('Пользователям старшего возраста было сложнее разобраться, как начать пользоваться продуктом после покупки.','Older users were more likely to get lost when trying to start using the product after purchasing.')}</li><li>${t('Пользователи не всегда понимали предложения о дополнительных покупках.','Some users misunderstood the additional purchase offers.')}</li><li>${t('Ожидания от рекламы не всегда совпадали с тем, что пользователи видели в приложении.','Expectations set by ads did not always match the in-app experience.')}</li></ul></section>
<section class="chapter" id="support"><div class="task-number">03 / ${t('ПОДДЕРЖКА','SUPPORT')}</div><div class="task-heading"><h2>${t('Помощь, которую<br>легко найти','Help that’s<br>easy to find')}</h2><div><p>${t('Поддержку было трудно найти в настройках. Столкнувшись с проблемой, пользователь мог запросить возврат или оставить негативный отзыв, не обратившись за помощью.','Support was difficult to find in settings. When something went wrong, users could request a refund or leave a negative review without reaching out for help.')}</p><p>${t('Я сделала вход заметнее и разделила два пути: найти ответ в FAQ или сразу связаться с поддержкой. До формы обращения стало можно дойти без перехода через FAQ.','I made the entry point more visible and separated two options: look for an answer in the FAQ or contact support directly. Users could now reach the contact form without going through the FAQ.')}</p></div></div><div class="screen-stage mint">${screen('settings','Заметный вход в поддержку в настройках','Visible support entry in settings')}${screen('faq','Выбор между FAQ и обращением в поддержку','FAQ or direct contact with support')}</div><div class="result-strip"><div class="metric"><div class="value">${t('+4,5','+4.5')} <small>${t('п. п.','pp')}</small></div><p>${t('дошли до сценария поддержки<br>17,1% против 12,6%','reached the support flow<br>17.1% vs 12.6%')}</p></div><div class="metric"><div class="value">${t('−10,9%','−10.9%')}</div><p>${t('показатель отписок · Day 1','unsubscribe rate · Day 1')}</p></div><div class="metric"><div class="value">${t('−9,2%','−9.2%')}</div><p>${t('показатель отписок · Day 7','unsubscribe rate · Day 7')}</p></div><div class="metric"><div class="value">${t('−5,7%','−5.7%')}</div><p>${t('показатель отписок · Day 30','unsubscribe rate · Day 30')}</p></div></div><p class="note">${t('Результаты эксперимента с доступом к поддержке. Решение выпустили в продукт. Эта задача показала мне, что даже небольшие изменения интерфейса могут дать заметный результат.','Results of the support access experiment. The solution was released. This task showed me that even small interface changes can make a meaningful difference.')}</p><div class="next-step"><h3>${t('Позже — чат с поддержкой','Later: support chat')}</h3><p>${t('Я предложила переписку с CX-агентом в формате мессенджера. Для этого нужно было сократить время ответа до 3–5 минут. Чат удалось внедрить.','I suggested a messenger-style chat with a CX agent. This required reducing response time to 3–5 minutes. The chat was implemented.')}</p></div></section>
<section class="chapter" id="webapp"><div class="split-task"><div><div class="task-number">04 / WEB → APP</div><h2>${t('Продолжить обучение<br>в приложении','Continue learning<br>in the app')}</h2><p>${t('Пользователи 55+ реже переходили из веба в мобильное приложение. Я изучила воронку и решения конкурентов.','Users aged 55+ were less likely to move from the web to the mobile app. I analyzed the funnel and reviewed competitors’ approaches.')}</p><p>${t('Предложила понятный следующий шаг, простую инструкцию и возможность остаться в браузере.','I proposed a clear next step, simple instructions and the option to continue in the browser.')}</p><div class="outcome">${t('Активация приложения выросла.<br>Решение распространили на все возрастные группы.','App activation increased.<br>The solution was extended to all age groups.')}</div></div><div class="screen-stage blue">${screen('webapp','Приглашение перейти в приложение','Invitation to continue in the app')}</div></div></section>
<section class="chapter" id="upsells"><div class="task-number">05 / ${t('ДОПОЛНЕНИЯ К ПОДПИСКЕ','SUBSCRIPTION ADD-ONS')}</div><div class="task-heading"><h2>${t('Понятная покупка.<br>Сохранённая выручка.','A clearer purchase.<br>Revenue preserved.')}</h2><p>${t('Одновременно поступило много требований от комплаенса. Макеты были разрознены, часть экранов из продукта отсутствовала в Figma. Нужно было ясно показать, что дополнение оплачивается отдельно, и сохранить выручку от этих покупок.','Many compliance requirements arrived at once. Designs were scattered and some live screens were missing from Figma. We needed to make it clear that add-ons were separate purchases while preserving their revenue.')}</p></div><div class="upsell-layout"><div class="upsell-story"><p>${t('В продукте было четыре направления: учебные челленджи по трейдингу и инвестициям, а также направления с ИИ-инструментами. Например, ботами, которые помогали пользователям вырабатывать и применять свою стратегию. Набор дополнений зависел от направления.','The product had four tracks: trading and investing learning challenges, plus tracks with AI tools, such as bots that helped users develop and apply their own strategies. Each track offered different add-ons.')}</p><div class="large">15 <span>${t('локалей','locales')}</span></div><p>${t('Согласовать тексты, оформление и условия покупки.','Align wording, design and purchase terms.')}</p><h3>${t('Восстановить актуальную картину','Restore the current designs')}</h3><p>${t('Восстановила недостающие макеты и работала над переводами. Вместе с разработчиками проверяла, что после покупки пользователь получает нужные учебные материалы.','I rebuilt missing screens and worked on translations. With developers, I checked that each purchase delivered the right learning materials.')}</p><h3>${t('Уточнить тексты и экраны','Clarify the copy and screens')}</h3><p>${t('Переработала интерфейсы и UX-тексты по требованиям комплаенса. Вместе с разработчиком запускала тесты и следила за выручкой.','I revised the interfaces and UX copy to meet compliance requirements. I ran experiments with a developer and tracked revenue.')}</p><div class="outcome">${t('Требования комплаенса учтены, языковые версии согласованы. ARPU апселлов — выручка на пользователя — не снизился. Отдельные варианты показали рост.','Compliance requirements were met and language versions aligned. Add-on ARPU — revenue per user — was maintained. Some variants showed an increase.')}</div></div><figure class="long-stage">${screen('upsell','Итоговый экран дополнительного предложения','Final add-on offer screen')}<figcaption>${t('Один из итоговых экранов дополнительных предложений','One of the final add-on offer screens')}</figcaption></figure></div></section>
<section class="chapter" id="research"><div class="task-number">06 / ${t('ИССЛЕДОВАНИЯ','RESEARCH')}</div><div class="research"><div><h2>${t('Один ресерч.<br>Два направления работы.','One study.<br>Two directions.')}</h2><p>${t('Изначально искали новые маркетинговые каналы. Я самостоятельно подготовила и провела интервью с пользователями из США на английском, затем систематизировала результаты.','The original goal was to find new marketing channels. I independently prepared and conducted interviews in English with US users, then synthesized the findings.')}</p><p>${t('В интервью проявились и другие трудности: ожидания от рекламы не всегда совпадали с опытом в продукте.','The interviews also revealed other difficulties: expectations set by ads did not always match the experience in the product.')}</p></div><div class="research-results"><div class="research-result"><span>01</span><div><b>${t('Для маркетинга','For marketing')}</b><p>${t('Собрала выводы для поиска новых каналов привлечения.','Compiled findings to inform the search for new acquisition channels.')}</p></div></div><div class="research-result"><span>02</span><div><b>${t('Для продукта','For the product')}</b><p>${t('Составила список проблем из интервью и предложила гипотезы для каждой.','Created a list of problems uncovered in interviews and proposed hypotheses for each.')}</p></div></div></div></div></section>
<section class="chapter" id="system">${intro('07 / '+t('ДИЗАЙН-СИСТЕМА','DESIGN SYSTEM'),t('Продумать даже<br>состояние ожидания','Designing even<br>the waiting moment'),t('Подготовила скелетоны для основных разделов приложения. Добавила компоненты и цветовые токены в дизайн-систему, описала анимацию и правила использования для разработчиков.','I designed skeleton loading states for the main app sections, added components and color tokens to the design system, and documented motion and usage rules for developers.'))}<div class="screen-stage" style="justify-content:center"><div class="skeleton-frame"><img src="assets/skeleton.png" alt="${t('Состояние загрузки симулятора','Simulator loading state')}" loading="lazy" width="375" height="812"><div class="skeleton-pulse" aria-hidden="true"></div></div>${screen('simulator','Загруженный экран симулятора','Loaded simulator screen')}</div><div class="screen-pair-labels"><span>${t('Содержимое загружается','Loading content')}</span><span>${t('Экран готов','Ready to use')}</span></div><button class="motion-control" id="motion-toggle" aria-pressed="false">${t('Ⅱ Пауза анимации','Ⅱ Pause animation')}</button></section><div class="case-end"><div><h2>${t('Спасибо за внимание','Thanks for reading')}</h2><p>${t('Обсудим задачу или познакомимся поближе?','Have a question or a project to discuss?')}</p></div><a class="text-link" href="mailto:l.zapevalova@gmail.com">${t('Написать мне','Get in touch')} ↗</a></div></main>`}
function render(){if(stopFlowerMotion)stopFlowerMotion();if(chapterObserver)chapterObserver.disconnect();document.documentElement.lang=lang;document.title=isCase?`Finelo — ${t('Люда Запевалова','Lyudmila Zapevalova')}`:t('Люда Запевалова — Product Designer','Lyudmila Zapevalova — Product Designer');document.body.id='top';document.body.classList.toggle('case-page',isCase);document.getElementById('app').innerHTML=header()+(isCase?finelo():home())+footer()+`<dialog class="lightbox" aria-label="${t('Просмотр макета','Design preview')}"><button class="close">${t('Закрыть','Close')} ×</button><img alt=""><p></p></dialog>`;bind();}
function bindFlowerMotion(){
  const cleanups=[...document.querySelectorAll('.flower,.about-flower')].map(flower=>{
  const petals=flower.querySelector('.flower-petals');
  const reduced=matchMedia('(prefers-reduced-motion: reduce)');
  let frame=0,angle=0,speed=0,previous=0,hovered=false;
  function tick(time){
    const dt=Math.min((time-previous)/1000,.05);previous=time;
    speed+=(hovered?180-speed:-speed)*(1-Math.exp(-dt*(hovered?7:3.8)));
    angle=(angle+speed*dt)%360;
    petals.setAttribute('transform',`rotate(${angle} 50 50)`);
    if(hovered||speed>.3)frame=requestAnimationFrame(tick);else{speed=0;frame=0;}
  }
  function start(){if(reduced.matches)return;hovered=true;if(!frame){previous=performance.now();frame=requestAnimationFrame(tick);}}
  function leave(){hovered=false;}
  function reset(){cancelAnimationFrame(frame);frame=0;speed=0;hovered=false;}
  flower.addEventListener('pointerenter',start);
  flower.addEventListener('pointerleave',leave);
  document.addEventListener('visibilitychange',reset);
  reduced.addEventListener('change',reset);
  return ()=>{reset();document.removeEventListener('visibilitychange',reset);reduced.removeEventListener('change',reset);};
  });
  stopFlowerMotion=()=>cleanups.forEach(cleanup=>cleanup());
}
function bind(){bindFlowerMotion();document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>{const y=scrollY;lang=b.dataset.lang;const u=new URL(location.href);u.searchParams.set('lang',lang);history.replaceState({},'',u);render();scrollTo(0,y)}));const dlg=document.querySelector('dialog');let sourceImage=null,closingPreview=false,previewAnimation=null;
const previewMotion=()=>!matchMedia('(prefers-reduced-motion: reduce)').matches;
function previewTransform(from,to){return `translate(${from.left-to.left}px,${from.top-to.top}px) scale(${from.width/to.width},${from.height/to.height})`;}
async function closeProductPreview(){
  if(closingPreview||!dlg.open)return;closingPreview=true;
  const im=dlg.querySelector('img');
  if(previewAnimation){try{await previewAnimation.finished;}catch{}previewAnimation=null;}
  dlg.classList.add('is-closing');
  if(sourceImage&&sourceImage.isConnected&&previewMotion()){
    const to=sourceImage.getBoundingClientRect(),from=im.getBoundingClientRect();
    try{await im.animate([{transform:'none',opacity:1},{transform:previewTransform(to,from),opacity:1}],{duration:320,easing:'cubic-bezier(.4,0,.2,1)',fill:'forwards'}).finished;}catch{}
  }
  if(sourceImage){sourceImage.style.visibility='';sourceImage.closest('button').classList.add('preview-return-focus');}
  dlg.close();closingPreview=false;
}
document.querySelectorAll('[data-image]').forEach(b=>b.addEventListener('click',async()=>{
  const im=dlg.querySelector('img'),product=!!b.closest('#product,#contribution');
  dlg.classList.remove('is-closing');dlg.classList.toggle('product-preview',product);
  im.getAnimations().forEach(a=>a.cancel());im.src=`assets/${b.dataset.image}.png`;im.alt=b.dataset.caption;
  dlg.querySelector('p').textContent=product?`${b.dataset.caption} · ${t('Нажми вне картинки или Esc, чтобы закрыть','Click outside the image or press Esc to close')}`:b.dataset.caption;
  dlg.classList.toggle('mobile-image',!['purchases','localization'].includes(b.dataset.image));
  sourceImage=product?(b.querySelector('.tools-frame')||b.querySelector('img')):null;
  if(product){try{await im.decode();}catch{}}
  const from=sourceImage?.getBoundingClientRect();dlg.showModal();document.body.style.overflow='hidden';
  if(product){dlg.setAttribute('tabindex','-1');dlg.focus({preventScroll:true});sourceImage.style.visibility='hidden';sourceImage.closest('button').classList.add('preview-source');
    if(previewMotion())previewAnimation=im.animate([{transform:previewTransform(from,im.getBoundingClientRect())},{transform:'none'}],{duration:360,easing:'cubic-bezier(.4,0,.2,1)'});
  }
}));
dlg.querySelector('.close').addEventListener('click',()=>dlg.close());
dlg.addEventListener('cancel',e=>{if(dlg.classList.contains('product-preview')){e.preventDefault();closeProductPreview();}});
dlg.addEventListener('click',e=>{if(dlg.classList.contains('product-preview')){if(e.target!==dlg.querySelector('img'))closeProductPreview();return;}if(e.target===dlg){const r=dlg.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dlg.close();}});
document.querySelectorAll('#product .screen,#contribution .screen').forEach(button=>{['blur','keydown'].forEach(event=>button.addEventListener(event,()=>button.classList.remove('preview-return-focus')));});
dlg.addEventListener('close',()=>{document.body.style.overflow='';if(sourceImage){sourceImage.style.visibility='';const sourceButton=sourceImage.closest('button');sourceButton.classList.remove('preview-source');sourceButton.focus({preventScroll:true});sourceImage=null;}dlg.querySelector('img').getAnimations().forEach(a=>a.cancel());});const motion=document.getElementById('motion-toggle');if(motion){const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let paused=reduced;function motionState(){document.getElementById('system').classList.toggle('paused',paused);motion.setAttribute('aria-pressed',String(paused));motion.textContent=paused?t('▷ Продолжить анимацию','▷ Play animation'):t('Ⅱ Пауза анимации','Ⅱ Pause animation')}motionState();if(reduced){motion.disabled=true;motion.textContent=t('Анимация отключена в настройках устройства','Animation disabled by your device preferences')}motion.addEventListener('click',()=>{paused=!paused;motionState()})}if(isCase)bindChapterNavigation();}
function bindChapterNavigation(){
  const sections=[...document.querySelectorAll('.chapter')],links=[...document.querySelectorAll('.chapter-nav a')];
  let pendingSection=null,frame=0,settleTimer=0;
  function selectSection(id){links.forEach(link=>{const active=link.hash==='#'+id;link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current');});}
  function update(){
    frame=0;if(pendingSection){selectSection(pendingSection);return;}
    const threshold=document.querySelector('.header-shell').getBoundingClientRect().height+document.querySelector('.chapter-nav').getBoundingClientRect().height+24;
    let current=sections[0];for(const section of sections){if(section.getBoundingClientRect().top<=threshold)current=section;else break;}
    if(current)selectSection(current.id);
  }
  function schedule(){if(!frame)frame=requestAnimationFrame(update);}
  function settle(){pendingSection=null;schedule();}
  function onScroll(){schedule();clearTimeout(settleTimer);if(pendingSection)settleTimer=setTimeout(settle,180);}
  const onClick=event=>{pendingSection=event.currentTarget.hash.slice(1);selectSection(pendingSection);clearTimeout(settleTimer);settleTimer=setTimeout(settle,180);};
  const onManualScroll=()=>{pendingSection=null;clearTimeout(settleTimer);schedule();};
  links.forEach(link=>link.addEventListener('click',onClick));
  window.addEventListener('scroll',onScroll,{passive:true});window.addEventListener('resize',schedule);window.addEventListener('wheel',onManualScroll,{passive:true});window.addEventListener('touchstart',onManualScroll,{passive:true});
  chapterObserver={disconnect(){cancelAnimationFrame(frame);clearTimeout(settleTimer);links.forEach(link=>link.removeEventListener('click',onClick));window.removeEventListener('scroll',onScroll);window.removeEventListener('resize',schedule);window.removeEventListener('wheel',onManualScroll);window.removeEventListener('touchstart',onManualScroll);}};
  update();
}

render();
